ENGINE_HELPER='\n\ndef engine_failure_projection(receipt):\n    """Returned supervisor DATA only; never transaction or cleanup authority."""\n    try:\n        import base64\n        if type(receipt) is not dict or set(receipt)!={\'returncode\',\'termination\',\'direct_child_reaped\',\'group_retired\',\'output\'}:\n            raise ValueError(\'closed returned engine receipt\')\n        raw=receipt[\'output\']\n        if (type(raw) is not bytes or len(raw)>1024**2 or type(receipt[\'returncode\']) is not int or\n            not -255<=receipt[\'returncode\']<=255 or receipt[\'termination\'] is not None or\n            any(type(receipt[k]) is not bool for k in (\'direct_child_reaped\',\'group_retired\'))):\n            raise ValueError(\'bounded typed returned engine receipt\')\n        tail=raw[-2048:]\n        row=dict(purpose=\'FRESH607_ENGINE_FAILURE_DATA_V1\',status=\'RETURNED_SUPERVISOR_OUTPUT_ONLY\',\n            returncode=receipt[\'returncode\'],termination=receipt[\'termination\'],\n            direct_child_reaped=receipt[\'direct_child_reaped\'],group_retired=receipt[\'group_retired\'],\n            output_bytes=len(raw),output_sha256=hashlib.sha256(raw).hexdigest(),\n            tail_codec=\'base64\',tail_bytes=len(tail),tail_base64=base64.b64encode(tail).decode(\'ascii\'),\n            tail_complete=len(raw)<=2048,transaction_authority=False,cleanup_authority=False)\n        if len(json.dumps(row,sort_keys=True,allow_nan=False).encode())>4096:\n            raise ValueError(\'bounded engine DATA frame\')\n        return row\n    except BaseException:\n        return dict(purpose=\'FRESH607_ENGINE_FAILURE_DATA_V1\',status=\'REFUSED_DIAGNOSTIC_SHAPE\',\n                    transaction_authority=False,cleanup_authority=False)\n'

