CLOCK_GUEST='\nFRESH607_CLOCK_CONTEXT = None\n\ndef fresh607_initialize_realtime(c):\n    """Initialize only this owned VM wall clock; monotonic deadlines are untouched."""\n    import re,time\n    context=FRESH607_CLOCK_CONTEXT;value=c.get(\'fresh607_realtime\')\n    need(type(context)is dict and set(context)=={\'schema_version\',\'purpose\',\'source\',\'run_id\',\'run_attempt\'} and\n         type(context[\'schema_version\'])is int and context[\'schema_version\']==1 and\n         context[\'purpose\']==\'SOURCE_OWNED_GENERIC16K_REALTIME_INIT_V1\' and\n         type(context[\'source\'])is str and re.fullmatch(\'[0-9a-f]{40}\',context[\'source\']) and\n         type(context[\'run_id\'])is str and re.fullmatch(\'[1-9][0-9]{0,19}\',context[\'run_id\']) and\n         type(context[\'run_attempt\'])is str and re.fullmatch(\'[1-9][0-9]{0,5}\',context[\'run_attempt\']),\n         \'closed current16K guest realtime context\')\n    need(type(value)is dict and set(value)==set(context)|{\'nonce\',\'workspace\',\'workspace_identity\',\'created_realtime_ns\'} and\n         all(value[k]==v for k,v in context.items()) and type(value[\'nonce\'])is str and\n         re.fullmatch(\'[0-9a-f]{32}\',value[\'nonce\']) and value[\'nonce\']==c[\'nonce\'] and\n         type(value[\'workspace\'])is str and value[\'workspace\'].startswith(\'/tmp/\') and\n         len(value[\'workspace\'].encode())<=4096 and \'..\'not in Path(value[\'workspace\']).parts and\n         str(Path(value[\'workspace\']))==value[\'workspace\'] and\n         type(value[\'workspace_identity\'])is list and len(value[\'workspace_identity\'])==4 and\n         all(type(n)is int and n>=0 for n in value[\'workspace_identity\']) and\n         type(value[\'created_realtime_ns\'])is int and 1_000_000_000_000_000_000<=value[\'created_realtime_ns\']<2**63,\n         \'exact current nonce/source/run/workspace clock contract\')\n    fields={}\n    for field in Path(\'/proc/cmdline\').read_text().split():\n        if field.startswith(\'caa_fresh607_\'):\n            key,separator,item=field.partition(\'=\')\n            need(separator and key not in fields,\'unique selected clock command-line field\');fields[key]=item\n    need(set(fields)=={\'caa_fresh607_realtime_ns\',\'caa_fresh607_clock_sha256\'} and\n         re.fullmatch(\'[1-9][0-9]{0,18}\',fields[\'caa_fresh607_realtime_ns\']),\n         \'closed launch-time realtime command-line DATA\')\n    expected=hashlib.sha256(json.dumps(value,sort_keys=True,separators=(\',\',\':\'),ensure_ascii=True).encode(\'ascii\')).hexdigest()\n    need(fields[\'caa_fresh607_clock_sha256\']==expected,\'same original nonce/current source/run/workspace clock binding\')\n    stamp=int(fields[\'caa_fresh607_realtime_ns\'])\n    need(value[\'created_realtime_ns\']<=stamp<=value[\'created_realtime_ns\']+9_600_000_000_000,\n         \'launch timestamp inside original owned VM lifetime\')\n    elapsed=time.monotonic_ns()\n    need(type(elapsed)is int and 0<=elapsed<=5_400_000_000_000,\'bounded original QEMU boot monotonic elapsed\')\n    time.clock_settime_ns(time.CLOCK_REALTIME,stamp+elapsed)\n    lower=stamp+time.monotonic_ns();observed=time.clock_gettime_ns(time.CLOCK_REALTIME);upper=stamp+time.monotonic_ns()\n    need(lower<=upper and lower-1_000_000_000<=observed<=upper+1_000_000_000,\n         \'owned guest realtime readback differs from current host launch plus boot elapsed\')\n'
